const packetsRaw = [
    require('./1'),
    require('./2'),
    require('./6'),
    require('./8'),
    require('./10'),
    require('./13'),
    require('./14'),
    require('./15'),
    require('./16'),
    require('./17'),
    require('./18'),
    require('./19'),
    require('./32'),
    require('./a'),
    require('./af1f'),
    require('./c'),
    require('./f'),
];

const packets = {};
packetsRaw.forEach((packet) => {
    if (packets[packet.code]) { throw new Error('Duplicate packet code ' + packet.code); }
    packets[packet.code] = packet;
});

const parser = (raf, productDescription) => {
    const packetCode = raf.readUShort();
    raf.skip(-2);
    const packetParser = packets[packetCode];
    if (!packetParser) {
        return null;
    }
    return packetParser.parser(raf, productDescription);
};

module.exports = { packets, parser };
